package grc721

import (
	"chain"
	"math/overflow"
	"strconv"

	"gno.land/p/nt/seqid/v0"
	"gno.land/p/nt/ufmt/v0"
)

// NewToken creates a core token and its ledger.
// rlm must be the caller's own captured cur (IsCurrent); its PkgPath becomes the unforgeable origRealm.
//
// Every successful call emits a NewToken event carrying the resulting Token.ID().
// Because Token's fields are unexported, NewToken is the only way a Token can come
// into existence, so this event makes token creation fully observable: an indexer
// that sees the same Token.ID() announced twice knows the realm built two
// independent ledgers behind one identifier, and that every later
// Mint/Burn/Transfer/Approval carrying that id is ambiguous. Such a realm is
// emitting untrustworthy events and should be flagged or ignored wholesale.
func NewToken(name, symbol string, id seqid.ID, rlm realm) (*Token, *PrivateLedger) {
	if !rlm.IsCurrent() {
		panic(ErrSpoofedRealm)
	}

	pkgPath := rlm.PkgPath()
	if pkgPath == "" {
		panic(ErrNotRealm)
	}

	if !validName(name) {
		panic(ErrInvalidName)
	}

	if !validSymbol(symbol) {
		panic(ErrInvalidSymbol)
	}

	// origRealm is the host path, with any ":subpath" synthesized by realm.Sub
	// stripped. guardHome strips the invoking path the same way, so a token
	// created from a sub frame is not locked out of its own host realm, and a
	// host's sub-realms are not falsely rejected. Token.ID() keeps the raw
	// pkgPath, so identities and the NewToken event are unaffected.
	origRealm, _, _ := chain.SplitPkgSubPath(pkgPath)

	ledger := &PrivateLedger{}
	token := &Token{
		id:        pkgPath + "." + symbol + "." + id.String(),
		name:      name,
		symbol:    symbol,
		ledger:    ledger,
		origRealm: origRealm,
	}
	ledger.token = token

	chain.Emit(
		NewTokenEvent,
		"token", token.id,
		"name", name,
		"symbol", symbol,
	)

	return token, ledger
}

func validName(name string) bool {
	if name == "" || len(name) > MaxNameLen {
		return false
	}

	for _, c := range name {
		if c < 0x20 || c == 0x7f {
			return false
		}
	}

	return true
}

func validSymbol(s string) bool {
	if s == "" || len(s) > MaxSymbolLen {
		return false
	}

	for _, c := range s {
		if !isAlnum(c) && c != '_' && c != '-' {
			return false
		}
	}

	return true
}

func isAlnum(c rune) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9')
}

func (tok *Token) GetName() string { return tok.name }

func (tok *Token) GetSymbol() string { return tok.symbol }

func (tok *Token) ID() string { return tok.id }

func (tok *Token) TotalSupply() int64 { return tok.ledger.totalSupply }

func (tok *Token) KnownAccounts() int { return tok.ledger.balances.Size() }

// EIP-721: balanceOf throws for queries about the zero address,
// since NFTs assigned to it are considered invalid.
func (tok *Token) BalanceOf(addr address) (int64, error) {
	if !addr.IsValid() {
		return 0, ErrInvalidAddress
	}

	return tok.ledger.balanceOf(addr), nil
}

func (tok *Token) OwnerOf(tid TokenID) (address, error) { return tok.ledger.ownerOf(tid) }

// EIP-721: getApproved throws for a token that is not a valid NFT, so a missing
// token is ErrInvalidTokenId and a live but unapproved one is ErrTokenIdNotApproved.
func (tok *Token) GetApproved(tid TokenID) (address, error) {
	if !tok.ledger.exists(tid) {
		return zeroAddress, ErrInvalidTokenId
	}

	addr := tok.ledger.tokenApprovals.Get(tid.String())
	if addr == nil {
		return zeroAddress, ErrTokenIdNotApproved
	}

	return addr.(address), nil
}

func (tok *Token) IsApprovedForAll(owner, operator address) bool {
	return tok.ledger.isApprovedForAll(owner, operator)
}

func (tok *Token) RenderHome() string {
	str := ""
	str += ufmt.Sprintf("# %s ($%s)\n\n", tok.name, tok.symbol)
	str += ufmt.Sprintf("* **Total supply**: %d\n", tok.ledger.totalSupply)
	str += ufmt.Sprintf("* **Known accounts**: %d\n", tok.KnownAccounts())

	return str
}

// RegisterExtension attaches an issuer-supplied hook set. Issuer-only (holds the
// PrivateLedger), which keeps the surface from being attacker-attachable — but the
// attachment is still a privilege: per the Extension doc, an attached hook can veto
// transfers (a panic aborts the transaction before the Transfer event is emitted) and
// adds gas to every movement.
// One extension per kind; a second registration of an attached kind panics.
func (led *PrivateLedger) RegisterExtension(ext Extension) {
	if ext == nil {
		panic("grc721: nil extension")
	}

	kind := ext.ExtensionKind()
	for _, e := range led.extensions {
		if e.ExtensionKind() == kind {
			panic("grc721: extension kind already registered: " + kind)
		}
	}

	led.extensions = append(led.extensions, ext)
}

func (led *PrivateLedger) ReadToken() *Token { return led.token }

func (led *PrivateLedger) Mint(to address, tid TokenID) error {
	if !to.IsValid() {
		return ErrInvalidAddress
	}

	if tid == "" {
		return ErrInvalidTokenId
	}

	if led.exists(tid) {
		return ErrTokenIdAlreadyExists
	}

	led.balances.Set(to.String(), overflow.Add64p(led.balanceOf(to), 1))
	led.owners.Set(tid.String(), to)
	led.totalSupply = overflow.Add64p(led.totalSupply, 1)

	for _, ext := range led.extensions {
		ext.OnMint(to, tid)
	}

	// Mint emits Transfer from the empty address (EIP-721); indexers reconstruct ownership from Transfer alone.
	chain.Emit(
		TransferEvent,
		"token", led.token.id,
		"from", "",
		"to", to.String(),
		"tokenId", tid.String(),
	)

	return nil
}

// Fans OnBurn out to every extension so per-token state cannot resurface if tid is re-minted.
func (led *PrivateLedger) Burn(tid TokenID) error {
	owner, err := led.ownerOf(tid)
	if err != nil {
		return err
	}

	tidStr := tid.String()
	led.tokenApprovals.Remove(tidStr)
	led.setBalance(owner, overflow.Sub64p(led.balanceOf(owner), 1))
	led.owners.Remove(tidStr)
	led.totalSupply = overflow.Sub64p(led.totalSupply, 1)

	for _, ext := range led.extensions {
		ext.OnBurn(tid)
	}

	// Burn emits Transfer to the empty address (EIP-721).
	chain.Emit(
		TransferEvent,
		"token", led.token.id,
		"from", owner.String(),
		"to", "",
		"tokenId", tidStr,
	)

	return nil
}

// spender must own or be approved for tid; callers derive it from a trusted per-frame identity.
func (led *PrivateLedger) TransferFrom(spender, from, to address, tid TokenID) error {
	if !led.isApprovedOrOwner(spender, tid) {
		return ErrCallerIsNotOwnerOrApproved
	}

	return led.transfer(from, to, tid)
}

// caller must own tid or be an approved operator of the owner.
// EIP-721: approving the zero address clears (revokes) any single-token approval.
func (led *PrivateLedger) Approve(caller, to address, tid TokenID) error {
	revoke := to == zeroAddress
	if !revoke && !to.IsValid() {
		return ErrInvalidAddress
	}

	owner, err := led.ownerOf(tid)
	if err != nil {
		return err
	}

	if owner == to {
		return ErrApprovalToCurrentOwner
	}

	if caller != owner && !led.isApprovedForAll(owner, caller) {
		return ErrCallerIsNotOwnerOrApproved
	}

	if revoke {
		led.tokenApprovals.Remove(tid.String())
	} else {
		led.tokenApprovals.Set(tid.String(), to)
	}

	chain.Emit(
		ApprovalEvent,
		"token", led.token.id,
		"owner", owner.String(),
		"to", to.String(), // empty for a revoke
		"tokenId", tid.String(),
	)

	return nil
}

func (led *PrivateLedger) SetApprovalForAll(owner, operator address, approved bool) error {
	if !owner.IsValid() || !operator.IsValid() {
		return ErrInvalidAddress
	}

	if owner == operator {
		return ErrApprovalToCurrentOwner
	}

	key := operatorKey(owner, operator)
	if approved {
		led.operatorApprovals.Set(key, approved)
	} else {
		led.operatorApprovals.Remove(key)
	}

	chain.Emit(
		ApprovalForAllEvent,
		"token", led.token.id,
		"owner", owner.String(),
		"to", operator.String(),
		"approved", strconv.FormatBool(approved),
	)

	return nil
}

func (led *PrivateLedger) transfer(from, to address, tid TokenID) error {
	if !from.IsValid() || !to.IsValid() {
		return ErrInvalidAddress
	}

	if from == to {
		return ErrCannotTransferToSelf
	}

	owner, err := led.ownerOf(tid)
	if err != nil {
		return err
	}

	if owner != from {
		return ErrTransferFromIncorrectOwner
	}

	tidStr := tid.String()
	led.tokenApprovals.Remove(tidStr)
	led.setBalance(from, overflow.Sub64p(led.balanceOf(from), 1))
	led.setBalance(to, overflow.Add64p(led.balanceOf(to), 1))
	led.owners.Set(tidStr, to)

	for _, ext := range led.extensions {
		ext.OnTransfer(from, to, tid)
	}

	chain.Emit(
		TransferEvent,
		"token", led.token.id,
		"from", from.String(),
		"to", to.String(),
		"tokenId", tidStr,
	)

	return nil
}

func (led *PrivateLedger) ownerOf(tid TokenID) (address, error) {
	owner := led.owners.Get(tid.String())
	if owner == nil {
		return zeroAddress, ErrInvalidTokenId
	}

	return owner.(address), nil
}

func (led *PrivateLedger) balanceOf(addr address) int64 {
	balance := led.balances.Get(addr.String())
	if balance == nil {
		return 0
	}

	return balance.(int64)
}

func (led *PrivateLedger) setBalance(addr address, balance int64) {
	if balance == 0 {
		led.balances.Remove(addr.String())

		return
	}

	led.balances.Set(addr.String(), balance)
}

func (led *PrivateLedger) isApprovedForAll(owner, operator address) bool {
	approved := led.operatorApprovals.Get(operatorKey(owner, operator))
	if approved == nil {
		return false
	}

	return approved.(bool)
}

func (led *PrivateLedger) isApprovedOrOwner(addr address, tid TokenID) bool {
	owner := led.owners.Get(tid.String())
	if owner == nil {
		return false
	}

	ownerAddr := owner.(address)
	if addr == ownerAddr || led.isApprovedForAll(ownerAddr, addr) {
		return true
	}

	approved := led.tokenApprovals.Get(tid.String())

	return approved != nil && approved.(address) == addr
}

func (led *PrivateLedger) exists(tid TokenID) bool {
	return led.owners.Has(tid.String())
}

func operatorKey(owner, operator address) string {
	return owner.String() + ":" + operator.String()
}

package grc721

import (
	"strings"
	"testing"

	"gno.land/p/nt/seqid/v0"
	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
	"gno.land/p/nt/urequire/v0"
)

func mustBalanceOf(t *testing.T, tok *Token, addr address) int64 {
	balance, err := tok.BalanceOf(addr)
	urequire.NoError(t, err)
	return balance
}

// newTestToken builds via same-realm cross (NewToken requires rlm.IsCurrent()).
func newTestToken(name, symbol string, id seqid.ID, rlm realm) (tok *Token, led *PrivateLedger) {
	func(cur realm) {
		tok, led = NewToken(name, symbol, id, cur)
	}(cross(rlm))
	return
}

type mockExtension struct {
	mints, transfers, burns int
	lastMintTo              address
	lastTransferFrom        address
	lastTransferTo          address
	lastBurn                TokenID
}

func (m *mockExtension) ExtensionKind() string { return "mock" }

func (m *mockExtension) OnMint(to address, tid TokenID) {
	m.mints++
	m.lastMintTo = to
}

func (m *mockExtension) OnTransfer(from, to address, tid TokenID) {
	m.transfers++
	m.lastTransferFrom = from
	m.lastTransferTo = to
}

func (m *mockExtension) OnBurn(tid TokenID) {
	m.burns++
	m.lastBurn = tid
}

// Value type holding a slice: uncomparable, so `==` on two of them is a runtime fault.
type journalExtension struct{ seen []TokenID }

func (e journalExtension) ExtensionKind() string                    { return "journal" }
func (e journalExtension) OnMint(to address, tid TokenID)           {}
func (e journalExtension) OnTransfer(from, to address, tid TokenID) {}
func (e journalExtension) OnBurn(tid TokenID)                       {}

var (
	alice = testutils.TestAddress("alice")
	bob   = testutils.TestAddress("bob")
	carl  = testutils.TestAddress("carl")
)

func TestNewToken(cur realm, t *testing.T) {
	tok, led := newTestToken("Foo NFT", "FOO", 0, cur)
	urequire.False(t, tok == nil, "token should not be nil")
	urequire.False(t, led == nil, "ledger should not be nil")

	uassert.Equal(t, "Foo NFT", tok.GetName())
	uassert.Equal(t, "FOO", tok.GetSymbol())
	uassert.Equal(t, int64(0), tok.TotalSupply())
	uassert.Equal(t, 0, tok.KnownAccounts())
	uassert.True(t, strings.HasSuffix(tok.ID(), ".FOO."+seqid.ID(0).String()), "ID must end with .symbol.id")
	uassert.True(t, strings.HasPrefix(tok.ID(), "gno.land/"), "ID must begin with the origin realm path")
	uassert.Equal(t, tok.ID(), led.ReadToken().ID())
}

func TestNewTokenDistinctIDs(cur realm, t *testing.T) {
	first, _ := newTestToken("Same", "DUP", 1, cur)
	second, _ := newTestToken("Same", "DUP", 2, cur)
	uassert.True(t, first.ID() != second.ID(), "distinct seqid must yield distinct IDs")

	a, _ := newTestToken("Same", "DUP", 3, cur)
	b, _ := newTestToken("Same", "DUP", 3, cur)
	uassert.Equal(t, a.ID(), b.ID())
}

func TestNewTokenValidation(cur realm, t *testing.T) {
	longName := strings.Repeat("a", MaxNameLen+1)
	maxName := strings.Repeat("a", MaxNameLen)
	longSymbol := strings.Repeat("A", MaxSymbolLen+1)

	tests := []struct {
		name       string
		tokenName  string
		symbol     string
		wantAbort  bool
		wantSubstr string
	}{
		{"valid name and symbol succeeds", "Foo", "FOO", false, ""},
		{"symbol with full slug charset succeeds", "Foo", "aZ9_-", false, ""},
		{"name at max length succeeds", maxName, "FOO", false, ""},
		{"empty name returns ErrInvalidName", "", "FOO", true, "invalid token name"},
		{"name over max length returns ErrInvalidName", longName, "FOO", true, "invalid token name"},
		{"name with low control char returns ErrInvalidName", "Foo\x01", "FOO", true, "invalid token name"},
		{"name with DEL control char returns ErrInvalidName", "Foo\x7f", "FOO", true, "invalid token name"},
		{"empty symbol returns ErrInvalidSymbol", "Foo", "", true, "invalid token symbol"},
		{"symbol over max length returns ErrInvalidSymbol", "Foo", longSymbol, true, "invalid token symbol"},
		{"symbol with space returns ErrInvalidSymbol", "Foo", "has space", true, "invalid token symbol"},
		{"symbol with dot returns ErrInvalidSymbol", "Foo", "FO.O", true, "invalid token symbol"},
		{"symbol with slash returns ErrInvalidSymbol", "Foo", "FO/O", true, "invalid token symbol"},
	}

	for _, tc := range tests {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			if tc.wantAbort {
				urequire.AbortsContains(t, cur, tc.wantSubstr, func() {
					newTestToken(tc.tokenName, tc.symbol, 0, cur)
				})
				return
			}
			tok, _ := newTestToken(tc.tokenName, tc.symbol, 0, cur)
			uassert.Equal(t, tc.tokenName, tok.GetName())
			uassert.Equal(t, tc.symbol, tok.GetSymbol())
		})
	}
}

func TestNewTokenRejectsSpoofedRealm(cur realm, t *testing.T) {
	// Stale outer cur in a fresh frame → ErrSpoofedRealm.
	urequire.AbortsContains(t, cur, "rlm does not match the current crossing frame", func() {
		stale := cur
		func(cur realm) {
			NewToken("Foo", "FOO", 0, stale)
		}(cross(cur))
	})
}

func TestMint(cur realm, t *testing.T) {
	tests := []struct {
		name    string
		action  func(led *PrivateLedger) error
		wantErr error
		verify  func(t *testing.T, tok *Token, led *PrivateLedger)
	}{
		{
			name: "mint to valid address succeeds",
			action: func(led *PrivateLedger) error {
				return led.Mint(alice, "1")
			},
			wantErr: nil,
			verify: func(t *testing.T, tok *Token, led *PrivateLedger) {
				uassert.Equal(t, int64(1), tok.TotalSupply())
				uassert.Equal(t, int64(1), mustBalanceOf(t, tok, alice))
				uassert.Equal(t, 1, tok.KnownAccounts())
				owner, err := tok.OwnerOf("1")
				urequire.NoError(t, err)
				uassert.Equal(t, alice, owner)
			},
		},
		{
			name: "mint to invalid address returns ErrInvalidAddress",
			action: func(led *PrivateLedger) error {
				return led.Mint(zeroAddress, "1")
			},
			wantErr: ErrInvalidAddress,
			verify: func(t *testing.T, tok *Token, led *PrivateLedger) {
				uassert.Equal(t, int64(0), tok.TotalSupply())
			},
		},
		{
			name: "mint duplicate token id returns ErrTokenIdAlreadyExists",
			action: func(led *PrivateLedger) error {
				urequire.NoError(t, led.Mint(alice, "1"))
				return led.Mint(bob, "1")
			},
			wantErr: ErrTokenIdAlreadyExists,
			verify: func(t *testing.T, tok *Token, led *PrivateLedger) {
				owner, err := tok.OwnerOf("1")
				urequire.NoError(t, err)
				uassert.Equal(t, alice, owner)
				uassert.Equal(t, int64(1), tok.TotalSupply())
			},
		},
		{
			name: "minting distinct ids to same owner accumulates balance",
			action: func(led *PrivateLedger) error {
				urequire.NoError(t, led.Mint(alice, "1"))
				return led.Mint(alice, "2")
			},
			wantErr: nil,
			verify: func(t *testing.T, tok *Token, led *PrivateLedger) {
				uassert.Equal(t, int64(2), mustBalanceOf(t, tok, alice))
				uassert.Equal(t, int64(2), tok.TotalSupply())
				uassert.Equal(t, 1, tok.KnownAccounts())
			},
		},
	}

	for _, tc := range tests {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			tok, led := newTestToken("Foo", "FOO", 0, cur)
			err := tc.action(led)
			if tc.wantErr == nil {
				uassert.NoError(t, err)
			} else {
				uassert.ErrorIs(t, err, tc.wantErr)
			}
			if tc.verify != nil {
				tc.verify(t, tok, led)
			}
		})
	}
}

func TestBurn(cur realm, t *testing.T) {
	tests := []struct {
		name    string
		action  func(led *PrivateLedger) error
		wantErr error
		verify  func(t *testing.T, tok *Token, led *PrivateLedger)
	}{
		{
			name: "burn existing token clears all state",
			action: func(led *PrivateLedger) error {
				urequire.NoError(t, led.Mint(alice, "1"))
				return led.Burn("1")
			},
			wantErr: nil,
			verify: func(t *testing.T, tok *Token, led *PrivateLedger) {
				uassert.Equal(t, int64(0), tok.TotalSupply())
				uassert.Equal(t, int64(0), mustBalanceOf(t, tok, alice))
				uassert.Equal(t, 0, tok.KnownAccounts())
				_, err := tok.OwnerOf("1")
				uassert.ErrorIs(t, err, ErrInvalidTokenId)
			},
		},
		{
			name: "burn clears any outstanding approval",
			action: func(led *PrivateLedger) error {
